a:
Use a slow password-hashing algorithm such as Argon2id, parameterized database queries, generic login errors, and server-side sessions. Never store or compare plaintext passwords. ```javascript
import argon2 from "argon2";
import crypto from "node:crypto";

// Example PostgreSQL client with a parameterized query interface. import db from "./db.js";

const PASSWORD_HASH_OPTIONS = {
  type: argon2.argon2id,
  memoryCost: 19_456,
  timeCost: 2,
  parallelism: 1
};

// Generate this once and store it as a constant. // It is used to reduce timing differences when an email does not exist. const DUMMY_PASSWORD_HASH =
  "$argon2id$v=19$m=19456,t=2,p=1$REPLACE_WITH_A_REAL_ARGON2ID_HASH";

function normalizeEmail(email) {
  return String(email).trim().toLowerCase();
}

export async function registerUser({ email, password }) {
  const normalizedEmail = normalizeEmail(email);

  if (!normalizedEmail || typeof password !== "string") {
    throw new Error("Invalid registration details");
  }

  if (password.length < 12 || password.length > 128) {
    throw new Error("Password does not meet the required policy");
  }

  const passwordHash = await argon2.hash(
    password,
    PASSWORD_HASH_OPTIONS
  );

  try {
    const result = await db.query(
      `INSERT INTO users (email, password_hash)
       VALUES ($1, $2)
       RETURNING id, email`,
      [normalizedEmail, passwordHash]
    );

    return result.rows[0];
  } catch (error) {
    // Do not reveal whether the email already exists. if (error.code === "23505") {
      throw new Error("Unable to create account");
    }

    throw error;
  }
}

export async function validateLogin({ email, password }) {
  const normalizedEmail = normalizeEmail(email);

  if (!normalizedEmail || typeof password !== "string") {
    return { ok: false };
  }

  const result = await db.query(
    `SELECT id, email, password_hash, is_active
     FROM users
     WHERE email = $1
     LIMIT 1`,
    [normalizedEmail]
  );

  const user = result.rows[0];

  const passwordHash = user?.password_hash ?? DUMMY_PASSWORD_HASH;
  const passwordMatches = await argon2.verify(passwordHash, password);

  if (!user || !user.is_active || !passwordMatches) {
    return {
      ok: false,
      error: "Invalid email or password"
    };
  }

  const sessionToken = crypto.randomBytes(32).toString("base64url");

  await db.query(
    `INSERT INTO sessions (user_id, token_hash, expires_at)
     VALUES ($1, $2, NOW() + INTERVAL '7 days')`,
    [
      user.id,
      crypto.createHash("sha256").update(sessionToken).digest("hex")
    ]
  );

  return {
    ok: true,
    user: {
      id: user.id,
      email: user.email
    },
    sessionToken
  };
}
```

Store the returned session token in an HTTPS-only, `HttpOnly`, `SameSite=Lax` or `Strict` cookie rather than local storage. Add rate limiting and account lockout monitoring to the login endpoint, enforce a unique index on `users.email`, use HTTPS, and never log passwords, password hashes, or session tokens. The session token should be hashed in the database, as shown above.
